<script setup lang="ts">
import { computed, ref } from 'vue'
import AppHeader from '../components/AppHeader.vue'
import RuleSurfaceScope from '../components/RuleSurfaceScope.vue'
import { allRulePages, findRulePage, quickReferencePages, ruleCategories, type RuleCategoryDefinition } from '../data/ruleCatalog'
import { loadRecentRuleSlugs } from '../services/ruleRecent'

const query=ref('')
const recentSlugs=ref(loadRecentRuleSlugs())
const defaultRecentSlugs=['attributes-skills','core-rules','character-creation','to-strike']
const recentPages=computed(()=>Array.from(new Set([...recentSlugs.value,...defaultRecentSlugs])).map(slug=>findRulePage(slug)).filter(Boolean).slice(0,4))
const searchResults=computed(()=>{const q=query.value.trim().toLowerCase();if(!q)return[];return allRulePages.filter(page=>`${page.title} ${page.summary} ${(page.keywords||[]).join(' ')}`.toLowerCase().includes(q))})
function clearSearch(){query.value=''}
function visibleCategoryPages(category:RuleCategoryDefinition){return category.id==='fundamentals'?category.pages:[category.landing,...category.pages]}
</script>

<template><main class="page rules-page rules-index-page"><AppHeader /><RuleSurfaceScope><div class="page-title-block rules-title-block"><h1>Rules</h1></div>
<label class="search-bar rules-primary-search" aria-label="Search rules"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/></svg><input v-model="query" type="search" placeholder="Search rules…" autocomplete="off" /><button v-if="query" type="button" class="search-clear" aria-label="Clear search" @click="clearSearch">×</button></label>
<section v-if="query" class="rules-index-panel card-surface"><header class="rules-index-heading"><span>Search Results</span><small>{{ searchResults.length }} found</small></header><div class="rules-index-list"><RouterLink v-for="result in searchResults" :key="result.slug" class="rules-index-row" :to="`/rules/read/${result.slug}`"><span><strong>{{ result.title }}</strong><small>{{ result.summary }}</small></span><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></RouterLink><div v-if="!searchResults.length" class="empty-inline">No matching rules.</div></div></section>
<template v-else><section class="rules-index-panel card-surface rules-recent-panel"><header class="rules-index-heading"><span>Recent</span></header><div class="rules-recent-grid"><RouterLink v-for="recent in recentPages" :key="recent!.slug" class="recent-rule-box" :to="`/rules/read/${recent!.slug}`"><strong>{{ recent!.title }}</strong><small>{{ recent!.summary }}</small></RouterLink></div></section>
<section class="rules-index-panel card-surface"><header class="rules-index-heading"><span>References</span></header><div class="rules-index-list"><RouterLink v-for="entry in quickReferencePages" :key="entry.slug" class="rules-index-row" :to="`/rules/read/${entry.slug}`"><span><strong>{{ entry.title }}</strong><small>{{ entry.summary }}</small></span><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></RouterLink></div></section>
<section class="rules-chapter-stack"><template v-for="category in ruleCategories" :key="category.id"><details class="rules-index-panel rules-chapter card-surface"><summary class="rules-index-heading rules-chapter-heading"><span><strong>{{ category.title }}</strong><small>{{ category.summary }}</small></span><svg viewBox="0 0 24 24"><path d="m6 9 6 6 6-6"/></svg></summary><div class="rules-index-list"><RouterLink v-for="entry in visibleCategoryPages(category)" :key="entry.slug" class="rules-index-row" :to="`/rules/read/${entry.slug}`"><span><strong>{{ entry.title }}</strong><small>{{ entry.summary }}</small></span><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></RouterLink></div></details>
</template></section></template></RuleSurfaceScope></main></template>

<style scoped>
