mes New Roman',serif}.recent-rule-box small{display:block;color:var(--ink-soft);line-height:1.35}.rules-chapter-stack{display:grid;gap:10px}.rules-chapter{margin:0}.rules-chapter-heading{list-style:none;cursor:pointer;border-bottom:0}.rules-chapter-heading::-webkit-details-marker{display:none}.rules-chapter-heading>span{display:grid;gap:3px}.rules-chapter-heading>span>small{color:var(--ink-soft);font-weight:600}.rules-chapter[open] .rules-chapter-heading{border-bottom:1px solid var(--line)}.rules-chapter[open] .rules-chapter-heading>svg{transform:rotate(180deg)}@media(max-width:620px){.rules-recent-grid{grid-template-columns:1fr}.rules-index-heading{align-items:flex-start}}
